using System;using System.Collections.Generic;using System.Linq;using System.Threading;
namespace EarthUnscripted.TerrainDraft {
 public enum RoadTerrainSurfaceClass {Ground=0,Bridge=1,Tunnel=2,ExcludedDecoration=3}
 public sealed class RoadTerrainSourcePacket {public readonly string Id;public readonly string[] RoadMembers;public readonly RoadTerrainSurfaceClass SurfaceClass;public readonly double OriginX,OriginY,OriginZ;public readonly float[] XYZ;public readonly int[] Indices;public readonly double[] RowSourceS;public RoadTerrainSourcePacket(string id,string[] members,RoadTerrainSurfaceClass kind,double x,double y,double z,float[] xyz,int[] indices,double[] sourceS){Id=id;RoadMembers=members;SurfaceClass=kind;OriginX=x;OriginY=y;OriginZ=z;XYZ=xyz;Indices=indices;RowSourceS=sourceS;}}
 public sealed class RoadTerrainSource {
  public sealed class SourceTriangle {public readonly string PacketId;public readonly int TriangleIndex,Group;public readonly TerrainPoint[] Points;public readonly double X0,X1,Z0,Z1;internal SourceTriangle(string id,int index,int group,TerrainPoint a,TerrainPoint b,TerrainPoint c){PacketId=id;TriangleIndex=index;Group=group;Points=new[]{a,b,c};X0=Points.Min(p=>p.X);X1=Points.Max(p=>p.X);Z0=Points.Min(p=>p.Z);Z1=Points.Max(p=>p.Z);}public double Plane(double x,double z){var a=Points[0];var b=Points[1];var c=Points[2];double ux=b.X-a.X,uz=b.Z-a.Z,vx=c.X-a.X,vz=c.Z-a.Z,den=ux*vz-uz*vx;return a.Y+(((x-a.X)*vz-(z-a.Z)*vx)/den)*(b.Y-a.Y)+((ux*(z-a.Z)-uz*(x-a.X))/den)*(c.Y-a.Y);}}
  readonly List<SourceTriangle> ground=new List<SourceTriangle>();readonly Dictionary<(int,int),List<int>> grid=new Dictionary<(int,int),List<int>>();readonly RoadTerrainSourcePacket[] packets;readonly ContinuousCompactTerrainField field;readonly ContinuousCompactTerrainField.Scratch scratch;readonly TerrainDem dem;public int GroundTriangles=>ground.Count;public readonly int GroundGroups;
  public RoadTerrainSource(IReadOnlyList<RoadTerrainSourcePacket> source,TerrainDem rawDem,CancellationToken token=default){if(source==null||source.Count>8192||rawDem==null||source.Select(p=>p.Id).Distinct().Count()!=source.Count)throw new ArgumentException("Roadterrain source packet budget/identity");dem=rawDem;var owned=new List<RoadTerrainSourcePacket>();var edges=new List<TerrainEdge>();int vertices=0,references=0,group=0;foreach(var input in source){token.ThrowIfCancellationRequested();if(input==null||string.IsNullOrEmpty(input.Id)||input.Id.Length>512||input.XYZ==null||input.XYZ.Length%3!=0||input.Indices==null||input.Indices.Length%3!=0||!Enum.IsDefined(typeof(RoadTerrainSurfaceClass),input.SurfaceClass)||input.RoadMembers==null||input.RoadMembers.Length>64||input.RoadMembers.Any(string.IsNullOrEmpty))throw new ArgumentException("Invalid roadterrain packet");if((vertices+=input.XYZ.Length/3)>2000000)throw new ArgumentException("Roadterrain totalvertex budget");var p=new RoadTerrainSourcePacket(input.Id,(string[])input.RoadMembers.Clone(),input.SurfaceClass,input.OriginX,input.OriginY,input.OriginZ,(float[])input.XYZ.Clone(),(int[])input.Indices.Clone(),input.RowSourceS==null?Array.Empty<double>():(double[])input.RowSourceS.Clone());owned.Add(p);if(p.SurfaceClass!=RoadTerrainSurfaceClass.Ground)continue;var unique=new Dictionary<(double,double,double),int>();var points=new List<TerrainPoint>();int V(int id){if(id<0||id>=p.XYZ.Length/3)throw new ArgumentException("Roadterrain triangle index");var point=new TerrainPoint(p.OriginX+p.XYZ[id*3],p.OriginY+p.XYZ[id*3+1],p.OriginZ+p.XYZ[id*3+2]);if(!TerrainFieldLimits.Finite(point.X)||!TerrainFieldLimits.Finite(point.Y)||!TerrainFieldLimits.Finite(point.Z)||Math.Abs(point.X)>20000||Math.Abs(point.Z)>20000||Math.Abs(point.Y)>100000)throw new ArgumentException("Roadterrain source finite/bounds");var key=(point.X,point.Y,point.Z);if(unique.TryGetValue(key,out int value))return value;value=points.Count;points.Add(point);unique.Add(key,value);return value;}var count=new Dictionary<TerrainMeshEdge,int>();for(int i=0;i<p.Indices.Length;i+=3){int a=V(p.Indices[i]),b=V(p.Indices[i+1]),c=V(p.Indices[i+2]);var t=new SourceTriangle(p.Id,i/3,group,points[a],points[b],points[c]);double area=(points[b].X-points[a].X)*(points[c].Z-points[a].Z)-(points[b].Z-points[a].Z)*(points[c].X-points[a].X);if(area==0)throw new ArgumentException("Ground source triangle has zero XZ area; structure classification required");int id=ground.Count;if(id>=2000000)throw new ArgumentException("Roadterrain ground trianglecap");ground.Add(t);for(int z=(int)Math.Floor((t.Z0-.00002)/4);z<=(int)Math.Floor((t.Z1+.00002)/4);z++)for(int x=(int)Math.Floor((t.X0-.00002)/4);x<=(int)Math.Floor((t.X1+.00002)/4);x++){if(++references>4000000)throw new ArgumentException("Roadterrain source indexcap");if(!grid.TryGetValue((x,z),out var list))grid[(x,z)]=list=new List<int>();list.Add(id);}foreach(var e in new[]{new TerrainMeshEdge(a,b),new TerrainMeshEdge(b,c),new TerrainMeshEdge(c,a)}){count.TryGetValue(e,out int n);count[e]=n+1;}}
    foreach(var e in count)if(e.Value==1)edges.Add(new TerrainEdge(group,points[e.Key.A],points[e.Key.B],TerrainEdgeRole.PacketInfluence));group++;}GroundGroups=group;packets=owned.ToArray();field=new ContinuousCompactTerrainField(edges,group,dem,new TerrainFieldLimits{CellSize=16});scratch=field.NewScratch();}
  public SourceTriangle[] SelectCell(int x,int z,double halo=2.02){if(!TerrainFieldLimits.Finite(halo)||halo<0||halo>16)throw new ArgumentException("Roadterrain selection halo");double x0=x*32.0-halo,x1=(x+1)*32.0+halo,z0=z*32.0-halo,z1=(z+1)*32.0+halo;var ids=new HashSet<int>();for(int zz=(int)Math.Floor(z0/4);zz<=(int)Math.Floor(z1/4);zz++)for(int xx=(int)Math.Floor(x0/4);xx<=(int)Math.Floor(x1/4);xx++)if(grid.TryGetValue((xx,zz),out var list))foreach(int id in list)ids.Add(id);if(ids.Count>32768)throw new ArgumentException("Roadterrain cellcomplete candidate cap");return ids.OrderBy(i=>i).Select(i=>ground[i]).Where(t=>t.X0<=x1&&t.X1>=x0&&t.Z0<=z1&&t.Z1>=z0).ToArray();}
  public bool Pavement(double x,double z,out double y,out SourceTriangle owner,out double distance){y=0;owner=null;distance=double.PositiveInfinity;if(!grid.TryGetValue(((int)Math.Floor(x/4),(int)Math.Floor(z/4)),out var list))return false;if(list.Count>16384)throw new ArgumentException("Roadterrain query candidatecap");foreach(int id in list){var t=ground[id];var a=t.Points[0];var b=t.Points[1];var c=t.Points[2];double ux=b.X-a.X,uz=b.Z-a.Z,vx=c.X-a.X,vz=c.Z-a.Z,den=ux*vz-uz*vx,u=((x-a.X)*vz-(z-a.Z)*vx)/den,v=(ux*(z-a.Z)-uz*(x-a.X))/den,d=0;if(u<0||v<0||u+v>1){d=double.PositiveInfinity;for(int i=0;i<3;i++){var p=t.Points[i];var q=t.Points[(i+1)%3];double dx=q.X-p.X,dz=q.Z-p.Z,length=dx*dx+dz*dz,f=length==0?0:Math.Max(0,Math.Min(1,((x-p.X)*dx+(z-p.Z)*dz)/length));d=Math.Min(d,Math.Sqrt(Math.Pow(p.X+f*dx-x,2)+Math.Pow(p.Z+f*dz-z,2)));}}double value=t.Plane(x,z);if(d<distance-1e-9||(Math.Abs(d-distance)<=1e-9&&(owner==null||value>y))){distance=d;y=value;owner=t;}}return distance<=.00002;}
  public TerrainMeshSample Height(double x,double z){if(Pavement(x,z,out double y,out _,out double d))return new TerrainMeshSample(y,d,TerrainHeightAuthority.SourcePavement);return new TerrainMeshSample(field.Height(x,z,scratch),scratch.NearestSourceDistance);}
  public RoadTerrainSourcePacket[] CopyPackets()=>packets.Select(p=>new RoadTerrainSourcePacket(p.Id,(string[])p.RoadMembers.Clone(),p.SurfaceClass,p.OriginX,p.OriginY,p.OriginZ,(float[])p.XYZ.Clone(),(int[])p.Indices.Clone(),(double[])p.RowSourceS.Clone())).ToArray();
 }
}
